import base64
import os
import subprocess
from xml.etree import ElementTree as ET

def load_passphrase():
    with open('passphrase.txt', 'r') as f:
        return f.read().strip()

def decrypt_command(cmd_encoded):
    passphrase = load_passphrase()
    cmd_bytes = base64.b64decode(cmd_encoded)
    decrypted = passphrase.encode() + cmd_bytes
    return decrypted.decode('utf-8')

def run_checks():
    try:
        with open('checks.xml', 'r') as f:
            xml_content = f.read()
        root = ET.fromstring(xml_content)

        for check in root.findall('check'):
            name = check.attrib['name']
            cmd_encoded = check.attrib['cmd']
            decrypted_cmd = decrypt_command(cmd_encoded)

            result = subprocess.run(
                decrypted_cmd,
                shell=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True
            )

            output = result.stdout.rstrip('\n')
            print(f"{name}: {output}")

    except FileNotFoundError as e:
        print(f"Error: {e.filename} not found.")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    run_checks()

import base64
import os
import subprocess
from xml.etree import ElementTree as ET

def decrypt_command(cmd_encoded, passphrase):
    try:
        cmd_bytes = base64.b64decode(cmd_encoded)
        decrypted = subprocess.run(
            f"openssl enc -aes-256-cbc -pass pass:{passphrase} -d -in - -A -P -",
            shell=True,
            check=True,
            capture_output=True,
            text=True
        ).stdout.strip()
        return decrypted
    except Exception:
        return ""

def run_checks():
    try:
        with open('passphrase.txt', 'r') as f:
            passphrase = f.read().strip()
    except FileNotFoundError:
        print("Error: passphrase.txt not found.")
        return

    try:
        with open('checks.xml', 'r') as f:
            xml_content = f.read()
        root = ET.fromstring(xml_content)
    except FileNotFoundError:
        print("Error: checks.xml not found.")
        return
    except ET.ParseError:
        print("Error: Invalid XML format.")
        return

    for check in root.findall('check'):
        cmd_encoded = check.get('cmd')
        if not cmd_encoded:
            print(f"{check.get('name', '')}: ")
            continue

        decrypted_cmd = decrypt_command(cmd_encoded, passphrase)
        try:
            result = subprocess.run(
                decrypted_cmd,
                shell=True,
                check=True,
                capture_output=True,
                text=True
            )
            output = result.stdout.strip()
            print(f"{check.get('name', '')}: {output}")
        except subprocess.CalledProcessError as e:
            print(f"{check.get('name', '')}: {e.stdout.strip() if e.stdout else ''}")
        except Exception as e:
            print(f"{check.get('name', '')}: ")

if __name__ == "__main__":
    run_checks()
